// Normalizes one Excel row into the shared Test Case JSON schema.
// See docs/architecture/milestone-1.md, section 7, for the field contract.
// Only ingestion-known fields are populated here; every other field is
// left null for downstream agents to fill in - ingestion never guesses
// values that belong to a later stage.
const row = $input.item.json;

const testCase = {
  test_id: String(row['Test ID']).trim(),
  description: row['Description'] ? String(row['Description']).trim() : null,
  steps: row['Steps'] ? String(row['Steps']).trim() : null,
  expected_result: row['Expected Result'] ? String(row['Expected Result']).trim() : null,
  actual_result: null,
  status: null,
  confidence: null,
  evidence: null,
  next_action: null,
  verification_type: row['Verification Type'] ? String(row['Verification Type']).trim() : null,
  tester: 'AI-Agent',
  date: null,
  notes: null,
  agent_reasoning: null,
  jira_key: null,
  run_id: $execution.id,
  workflow_version: null,
  prompt_version: null,
  model_version: null,
  repo_commit: null,
  timestamp: new Date().toISOString(),
  human_verdict: null
};

return { json: testCase };
